import React, { useState, useEffect } from 'react';
import { io } from 'socket.io-client';

const socket = io('http://localhost:5000');

const ChatWindow = ({ currentUser, selectedUser }) => {
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    socket.on('receive_message', (data) => {
      setMessages(prev => [...prev, { ...data, incoming: true }]);
    });
  }, []);

  const sendMessage = () => {
    if (message.trim() === '') return;
    socket.emit('send_message', {
      toUserId: selectedUser.userId,
      message,
      fromUser: currentUser,
    });
    setMessages(prev => [...prev, { message, fromUser: currentUser, incoming: false }]);
    setMessage('');
  };

  return (
    <div className="chat-window">
      <div className="messages">
        {messages.map((msg, i) => (
          <div key={i} className={msg.incoming ? 'message incoming' : 'message outgoing'}>
            <b>{msg.incoming ? msg.fromUser.name : 'You'}:</b> {msg.message}
          </div>
        ))}
      </div>
      <div className="chat-input">
        <input 
          value={message} 
          onChange={(e) => setMessage(e.target.value)} 
          placeholder="Type a message..."
        />
        <button onClick={sendMessage}>Send</button>
      </div>
    </div>
  );
};

export default ChatWindow;
